class Wallet
  attr_reader :cents

  def initialize(cents)
    @cents = cents
  end

  def deposit(amount)
    raise ArgumentError, "deposit must be positive" unless amount.positive?
    @cents += amount
  end
end

wallet = Wallet.new(250)
wallet.deposit(75)
puts wallet.cents
